import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("plan history", () => {
  test("plan history", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const pl_ada_1 = ui.must(await ui.addPlan(pg_uma, p_ada, {"amount": "10.00", "start": "2026-03-01", "end": "2026-03-20", "every": "3"}));
    expect(await ui.generatePlans(pg_uma)).toBe(1);
    const c_ada_0 = await ui.claimAt(pg_uma, p_ada, 0);
    await ui.setToday(pg_uma, "2026-03-05");
    expect(await ui.generatePlans(pg_uma)).toBe(1);
    const c_ada_1 = await ui.claimAt(pg_uma, p_ada, 1);
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.planAmount(pg_uma, pl_ada_1, "20.00")).toBe(true);
    expect(await ui.planAmount(pg_uma, pl_ada_1, "1.005")).toBe(false);
    await ui.setToday(pg_uma, "2026-03-11");
    expect(await ui.generatePlans(pg_uma)).toBe(2);
    const c_ada_2 = await ui.claimAt(pg_uma, p_ada, 2);
    const c_ada_3 = await ui.claimAt(pg_uma, p_ada, 3);
    expect(await ui.planAmount(pg_uma, pl_ada_1, "5.00")).toBe(true);
    await ui.setToday(pg_uma, "2026-03-14");
    expect(await ui.generatePlans(pg_uma)).toBe(1);
    const c_ada_4 = await ui.claimAt(pg_uma, p_ada, 4);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("10.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_4).getByTestId("claim-date")).toHaveText("2026-03-13");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_4).getByTestId("claim-amount")).toHaveText("5.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_4).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-date")).toHaveText("2026-03-10");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-amount")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_3).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-date")).toHaveText("2026-03-07");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-amount")).toHaveText("20.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-date")).toHaveText("2026-03-04");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-amount")).toHaveText("10.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-date")).toHaveText("2026-03-01");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-amount")).toHaveText("10.00");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("OPEN");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ada_1).getByTestId("plan-generated")).toHaveText("5");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ada_1).getByTestId("plan-next-dates")).toHaveText("2026-03-16, 2026-03-19");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ada_1).getByTestId("plan-paused")).toHaveText("no");
    await expect(pg_uma.getByTestId("plan-row-" + pl_ada_1).getByTestId("plan-change-line")).toHaveText(["2026-03-05 amount=20.00", "2026-03-11 amount=5.00"]);
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PLAN_ADDED sheet=${sheet} by=uma name=Ada amount=10.00 start=2026-03-01 every=3 end=2026-03-20`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=0.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-04`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01 number=FY2026-1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=1.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=10.00 due-total=1.00 overdue-total=0.00`,
      `PLAN_CHANGED sheet=${sheet} by=uma name=Ada start=2026-03-01 amount=20.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=1.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-07`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-10`,
      `PLAN_CHANGED sheet=${sheet} by=uma name=Ada start=2026-03-01 amount=5.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=1.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=5.00 date=2026-03-13`
    ]);
  });
  test("plan history scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const was = await shown(page.getByTestId('bulk-retired'));
  await page.getByTestId('bulk-retire').click();
  const n = await countAfter(page, page.getByTestId('bulk-retired'), page.getByTestId('person-error'), 'bulk retire', was);
  return n === null ? null : Number(n);
}

type PlanFields = { amount: string; start: string; every?: string; day?: string; end: string; sheet?: string };

/** Add a plan on the person's row: the new plan row's id, or null when refused. */
export async function addPlan(page: Page, personId: string, f: PlanFields): Promise<string | null> {
  const r = row(page, personId);
  const plans = r.locator('[data-testid^="plan-row-"]');
  const before = await ids(plans, 'plan-row-');
  await r.getByTestId('plan-form-amount').fill(f.amount);
  await r.getByTestId('plan-form-start').fill(f.start);
  await setField(r, 'plan-form-every', f.every);
  await setField(r, 'plan-form-day', f.day);
  await setField(r, 'plan-form-sheet', f.sheet);
  await r.getByTestId('plan-form-end').fill(f.end);
  await r.getByTestId('plan-form-submit').click();
  let added: string | null = null;
  const ok = await until(page, async () => {
    const now = (await freshRows(plans, 'plan-row-', before, []))[0];
    added = now ? now.id : null;
    return added !== null;
  }, r.getByTestId('plan-error'), 'add plan');
  return ok ? added : null;
}

/** Pause (true) or resume (false) a plan: true once the plan shows it. */
export async function planPause(page: Page, planId: string, on: boolean): Promise<boolean> {
  const r = page.getByTestId(`plan-row-${planId}`);
  const done = async () => (await shown(r.getByTestId('plan-paused'))) === (on ? 'yes' : 'no');
  const already = await done();
  await r.getByTestId(on ? 'plan-pause' : 'plan-resume').click();
  return until(page, done, r.getByTestId('plan-error'), 'plan pause', already);
}

/** Change a plan's amount: true once the plan shows one more change line. */
export async function planAmount(page: Page, planId: string, amount: string): Promise<boolean> {
  const r = page.getByTestId(`plan-row-${planId}`);
  const lines = r.getByTestId('plan-change-line');
  const was = await lines.count();
  await r.getByTestId('plan-amount').fill(amount);
  await r.getByTestId('plan-amount-save').click();
  return until(page, async () => (await lines.count()) > was, r.getByTestId('plan-error'), 'plan amount');
}

/** Generate the plans' claims: how many were made, or null when refused. */
export async function generatePlans(page: Page): Promise<number | null> {
  const cell = page.getByTestId('plan-generated-count');
  const was = await shown(cell);
  await page.getByTestId('plan-generate').click();
  const n = await countAfter(page, cell, page.getByTestId('plan-generate-error'), 'generate plans', was);
  return n === null ? null : Number(n);
}

/** Flag the person with a reason until a date: true once the row shows `shows` (the reason while
 *  the flag is in force; nothing when its until-date is already past, in which case the step
 *  counts as taken once no error has shown for a while). */
export async function flag(page: Page, personId: string, reason: string, until_: string, shows: string = reason): Promise<boolean> {
  const r = row(page, personId);
  const done = async () => (await shown(r.getByTestId('person-flag-shown'))) === shows.trim();
  const already = shows.trim() === '' || await done();
  await r.getByTestId('person-flag-reason').fill(reason);
  await r.getByTestId('person-flag-until').fill(until_);
  await r.getByTestId('person-flag').click();
  return until(page, done, r.getByTestId('person-error'), 'flag', already);
}

/** Set the person's approver: true once the row shows the user. */
export async function setApprover(page: Page, personId: string, user: string): Promise<boolean> {
  const r = row(page, personId);
  const done = async () => (await shown(r.getByTestId('person-approver'))) === user.trim();
  const already = await done();
  await r.getByTestId('person-approver-input').fill(user);
  await r.getByTestId('person-approver-save').click();
  return until(page, done, r.getByTestId('person-error'), 'set approver', already);
}

